"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["37132"],{4627(e){e.exports=JSON.parse('{"id":"F440","slug":"urr-implicit-tax","name":"Capital Controls: Reserve Requirement Implicit Tax","subject":"International Finance","section":"Global Finance","topic":"Capital controls","level":"Intermediate","aliases":["capital controls","unremunerated reserve requirement","Tobin tax","cost of controls","Chile encaje"],"formula":{"latex":"\\\\tau_{URR}=i\\\\,k\\\\,\\\\frac{T_{res}}{T_{loan}},\\\\quad \\\\tau_{Tobin}=t\\\\,\\\\frac{365}{h}","also":[],"text":"Implicit tax of an unremunerated reserve requirement (annualized) = interest rate x share of the inflow that must be deposited x (years the deposit is held / years of the loan); Transaction tax annualized = tax per transaction x 365 / holding days"},"symbols":[{"symbol":"i","meaning":"Market interest rate","unit":"per year"},{"symbol":"k","meaning":"Share of each capital inflow that must be deposited with the central bank at no interest","unit":"percent"},{"symbol":"T_res, T_loan","meaning":"Years the deposit must be held and years the funding lasts","unit":"years"},{"symbol":"t, h","meaning":"Tax rate per transaction and the holding period in days","unit":"percent, days"}],"when_to_use":"Use it to see why short-term capital is hit hardest by controls. A requirement to deposit part of an inflow for a year is the same as a fixed fee, and that fee is far heavier per year on a 3-month loan than on a 3-year one. A small transaction tax works in the same way. These measures aim to discourage hot money but can also raise costs for firms, and they tend to be evaded over time.","worked_example":{"problem":"A rule requires 30% of inflows to be deposited for one year at no interest. Market rates are 5%. Compare a 3-month loan with a 3-year loan, and a 0.1% transaction tax on a 5-day trade.","inputs":{"i":5,"k":30,"tr":1,"tl1":0.25,"tl2":3,"t":0.1,"h":5},"steps":[{"label":"Implicit tax, short loan","working":"0.05 x 0.3 x 1 / 0.25","value":"6.00%"},{"label":"Implicit tax, long loan","working":"0.05 x 0.3 x 1 / 3","value":"0.50%"},{"label":"Transaction tax annualized for the short hold","working":"0.001 x 365 / 5","value":"7.3%"},{"label":"Transaction tax annualized for a one-year hold","working":"0.001 x 365 / 365","value":"0.10%"}],"answer":"For a 3-month loan the implicit tax is 6.00% a year, and for a 3-year loan it is 0.50%. A 0.1% tax on a 5-day trade is 7.3% annualized, and on a 365-day holding it is 0.10%."},"calculator":{"available":true,"inputs":[{"id":"i","label":"Market interest rate","unit":"%","type":"number","default":5,"hint":""},{"id":"k","label":"Share deposited","unit":"%","type":"number","default":30,"hint":""},{"id":"tr","label":"Years the deposit must be held","unit":"years","type":"number","default":1,"hint":""},{"id":"tl1","label":"Short loan maturity","unit":"years","type":"number","default":0.25,"hint":""},{"id":"tl2","label":"Long loan maturity","unit":"years","type":"number","default":3,"hint":""},{"id":"t","label":"Transaction tax rate","unit":"%","type":"number","default":0.1,"hint":""},{"id":"h","label":"Holding period of the trade","unit":"days","type":"number","default":5,"hint":"","min":1}],"checks":[{"expr":"tr>0 and tl1>0 and tl2>0","message":"The periods must be above zero."}],"steps":[{"id":"t1","label":"Implicit tax, short loan","expr":"i*k*tr/tl1","format":"pct2"},{"id":"t2","label":"Implicit tax, long loan","expr":"i*k*tr/tl2","format":"pct2"},{"id":"tobin","label":"Transaction tax annualized for the short hold","expr":"t*365/h","format":"pct1"},{"id":"tobin2","label":"Transaction tax annualized for a one-year hold","expr":"t*365/365","format":"pct2"}],"results":["t1","t2","tobin"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"t1":0.06,"t2":0.005,"tobin":0.073,"tobin2":0.001}},"finder":{"finds":"The effective annual cost of a capital control","needs":"Rate, deposit share, holding periods, tax rate"},"related":[{"slug":"reserve-adequacy","name":"Reserve Adequacy Metrics"},{"slug":"covered-interest-arbitrage","name":"Covered Interest Parity and Arbitrage"},{"slug":"balance-of-payments-identity","name":"Balance of Payments Identity"}],"related_ids":["F439","F434","F447"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>\u03C4</mi><mrow><mi>U</mi><mi>R</mi><mi>R</mi></mrow></msub><mo>=</mo><mi>i</mi><mtext>\u2009</mtext><mi>k</mi><mtext>\u2009</mtext><mfrac><msub><mi>T</mi><mrow><mi>r</mi><mi>e</mi><mi>s</mi></mrow></msub><msub><mi>T</mi><mrow><mi>l</mi><mi>o</mi><mi>a</mi><mi>n</mi></mrow></msub></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mi>\u03C4</mi><mrow><mi>T</mi><mi>o</mi><mi>b</mi><mi>i</mi><mi>n</mi></mrow></msub><mo>=</mo><mi>t</mi><mtext>\u2009</mtext><mfrac><mn>365</mn><mi>h</mi></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\tau_{URR}=i\\\\,k\\\\,\\\\frac{T_{res}}{T_{loan}},\\\\quad \\\\tau_{Tobin}=t\\\\,\\\\frac{365}{h}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"capital-allocation-line","name":"Capital Allocation Line and Optimal Risky Weight"},"next":{"slug":"capital-gains-tax","name":"Capital Gains and Dividend Tax"},"lesson":null,"total":522}')}}]);